#ifndef OPCIONES_REGLA_H
#define OPCIONES_REGLA_H

// Domaine : 0 <= puntos <= 20 et 0 <= minimo <= 20.
bool admitir(int puntos, int minimo);

#endif

#include "regla.h"

bool admitir(int puntos, int minimo) {
    return puntos >= minimo;
}

#include "regla.h"

bool admitir(int puntos, int minimo) {
    return puntos > minimo;
}

#include "regla.h"
#include <iostream>

int main() {
    int puntos{0};
    int minimo{0};
    if (!(std::cin >> puntos >> minimo) ||
        puntos < 0 || puntos > 20 || minimo < 0 || minimo > 20) {
        std::cerr << "Entrée invalide";
        return 2;
    }
    std::cout << admitir(puntos, minimo);
    return 0;
}

